import { apiFetch } from './client'
import type { Visit } from './types'

// Matches VisitCheckIn (backend/app/visits/schemas.py)
export interface VisitCheckInInput {
  idempotency_key: string
  zone_id?: string | null
  latitude: number
  longitude: number
  notes?: string | null
  external_reference?: string | null
}

export function checkIn(input: VisitCheckInInput): Promise<Visit> {
  return apiFetch<Visit>('/api/v1/visits/check-in', {
    method: 'POST',
    body: JSON.stringify(input),
  })
}

export function checkOut(visitId: string): Promise<Visit> {
  return apiFetch<Visit>(`/api/v1/visits/${visitId}/check-out`, {
    method: 'POST',
  })
}

// Hand-written mirrors of the backend's Pydantic response schemas
// (backend/app/{pings,visits,tasks,goals}/schemas.py), trimmed to the
// rep-scoped fields this app actually needs -- no admin-only fields.

export type { AuthUser } from '../auth/AuthContext'

// Matches PingOut (backend/app/pings/schemas.py)
export interface Ping {
  id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

// Matches VisitOut (backend/app/visits/schemas.py)
export interface Visit {
  id: string
  rep_id: string
  zone_id: string | null
  checked_in_at: string
  checked_out_at: string | null
  latitude: number
  longitude: number
  geofence_verified: boolean
  notes: string | null
  external_reference: string | null
}

// Matches TaskOut (backend/app/tasks/schemas.py)
export interface Task {
  id: string
  assigned_to: string
  title: string
  due_date: string | null
  status: string
  priority: string
  external_reference: string | null
  created_at: string
  completed_at: string | null
}

// Matches GoalOut (backend/app/goals/schemas.py)
export interface Goal {
  id: string
  rep_id: string
  metric_type: string
  target: number
  period_start: string
  period_end: string
  manual_value: number | null
  created_at: string
}

